UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Во время Крутой гонки тебе придется пролететь мимо клетчатого флага, чтобы тебе засчитали проход через контрольную точку.', `VerifiedBuild`=19865 WHERE `ID`=57251 AND `locale`='ruRU';
