UPDATE `broadcast_text_locale` SET `MaleText_lang`='Здравствуйте, господин Грязный Коготь. У меня нет уверенности, что вы меня узнаете... я помогаю фермеру Юну.', `FemaleText_lang`='Здравствуйте, господин Грязный Коготь. У меня нет уверенности, что вы меня узнаете... я помогаю фермеру Юну.', `VerifiedBuild`=19865 WHERE `ID`=57643 AND `locale`='ruRU';
UPDATE `broadcast_text_locale` SET `MaleText_lang`='ОЛОЛО FINALE CINEMATIC WILL BE PLAYED HERE!!!! DARK NAARU IS SUMMONED DOWN & VELEN SACRIFICES HIMSELF TO PURIFY IT! NAARU WASHES THE FIELD WITH HOLY ENERGY, INSPIRING THE DRAENEI FIGHTING ON THE FIELD!', `FemaleText_lang`='ОЛОЛО FINALE CINEMATIC WILL BE PLAYED HERE!!!! DARK NAARU IS SUMMONED DOWN & VELEN SACRIFICES HIMSELF TO PURIFY IT! NAARU WASHES THE FIELD WITH HOLY ENERGY, INSPIRING THE DRAENEI FIGHTING ON THE FIELD!', `VerifiedBuild`=19865 WHERE `ID`=57898 AND `locale`='ruRU';
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Я тебя уничтожу... как только смогу подняться.', `VerifiedBuild`=19865 WHERE `ID`=58620 AND `locale`='ruRU';
UPDATE `broadcast_text_locale` SET `MaleText_lang`='$n, ошибки – это всего лишь уроки, которые мы еще не усвоили. И лучше всего тебя характеризует то, как ты реагируешь на эти ошибки.', `VerifiedBuild`=19865 WHERE `ID`=58628 AND `locale`='ruRU';
UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Папочка мне эту историю сто раз рассказывал!$B$BВо времена великой засухи времена, ясное дело, были тяжелые. Крестьяне пытались смачивать посевы своей слюной: настолько все было плохо. Весь город страдал от жажды!$B$BИ что сделал дедушка фермера Юна? Он собрался и посреди ночи, запряг в повозку мушана и отправился в путь.$B$BОн поехал к озеру у подножья вершины Кунь-Лай. Он загрузил в свою повозку сотни бочек свежей воды и отправился обратно$B$BНи на минуту он не останавливался. Да и как он мог, ведь в его городе умирали люди! Он доехал до своей фермы, и его мушан упал замертво!$B$BНо нам хватило воды на целый город, и еще осталось на весенний урожай.$B$BВот так дедушка Юна спас Полугорье!', `VerifiedBuild`=19865 WHERE `ID`=58669 AND `locale`='ruRU';
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Посади один лук-порей – получишь два!', `VerifiedBuild`=19865 WHERE `ID`=59154 AND `locale`='ruRU';
UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Вовремя ты $gспросил:спросила;. Надоело ждать, пока фермер Юн меня заметит. Иди вперед, я скоро подойду.', `VerifiedBuild`=19865 WHERE `ID`=59211 AND `locale`='ruRU';
