UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Попытайся понять, груммель. Это храм Нюцзао, великого Черного Быка. Мы его слуги и хранители этого храма. Мы не "заменяем яков".', `VerifiedBuild`=19865 WHERE `ID`=61113 AND `locale`='ruRU';
