UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Некоторые считают этих яков низшими существами, способными только жевать траву и выполнять тяжелую работу. Мало кто понимает истинную красоту, которой обладают эти существа – потомки Черного Быка.', `VerifiedBuild`=19865 WHERE `ID`=62039 AND `locale`='ruRU';
