UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Помни, что в Крутой гонке тебе предстоит состязаться с другими послушниками нашего ордена.', `VerifiedBuild`=19865 WHERE `ID`=67074 AND `locale`='ruRU';
UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Мастер Кистан собирается восстановить здоровье у ближайшей статуи Нефритовой Змеи. Примените против нее "Руку-копье" и победите ее до того, как она исцелится!', `VerifiedBuild`=19865 WHERE `ID`=67173 AND `locale`='ruRU';
